import os
import sys
import json
import math


A = 2.382892
B = 2.613343
C = 0.566573
D = -0.845423


def _trigram_weight(tri):
    o0, o1, o2 = (ord(ch) for ch in tri)
    return math.sin(A * o0 + B * o1 + C * o2 + D)


def score(text):
    ll = 0.0
    for i in range(len(text) - 2):
        ll += _trigram_weight(text[i:i + 3])
    return {"score": round(ll, 6)}


class Predict(object):
    def __init__(self):
        pass

    def predict(self, inputs):
        # inputs is the full request payload dict: {"instances": [...]}
        instances = inputs.get("instances", inputs if isinstance(inputs, list) else [inputs])
        predictions = []
        for instance in instances:
            if isinstance(instance, list):
                text = instance[0] if len(instance) > 0 else ""
            elif isinstance(instance, dict):
                text = instance.get("text", instance.get("inputs", str(instance)))
            else:
                text = str(instance)
            predictions.append(score(text))
        return {"predictions": predictions}

